 chart:'<path d="M3 3v18h18"/><circle cx="8" cy="15" r="1.5"/><circle cx="12" cy="10" r="1.5"/><circle cx="18" cy="6" r="1.5"/><path d="m7 9 1-3m8 10 4-3"/>',
 network:'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="5" r="2"/><circle cx="20" cy="5" r="2"/><circle cx="5" cy="20" r="2"/><circle cx="21" cy="18" r="2"/><path d="m6 7 4 3m4 0 4-3m-8 7-4 4m9-5 4 3"/>',
 map:'<path d="m9 3-7 3v15l7-3 6 3 7-3V3l-7 3-6-3Zm0 0v15m6-12v15"/>',
 note:'<path d="M14 3H5v18h14V9M14 3v6h5l-5-6ZM8 13h8M8 17h5"/>',
 bookmark:'<path d="M6 3h12v19l-6-4-6 4V3Z"/>',
