 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 quiz:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4m0 3v.1"/>',
 external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',
 protein:'<path d="M5 6c5-5 17 1 14 5S2 8 3 14s18 8 18 1S6 3 6 13s12 8 11-1S2 4 5 6Z"/>',
 rna:'<path d="M2 15c5-12 13 12 20-6M5 11l2-6m2 8 2-6m2 10 3-6m2 4 3-5"/>',
 mitochondria:'<path d="M6 5C-2 11 5 24 15 19S24 2 16 3s-6-1-10 2Z"/><path d="m8 7-2 5 5-2-2 6 6-4-1 5 4-5-3-3 3-3"/>',
